"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[92889],{24336:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>h,default:()=>u,frontMatter:()=>s,metadata:()=>r,toc:()=>d});var o=n(31085),a=n(71184);const s={sidebar_position:22,slug:"/bible/Josue/Josue_22",title:"Josue 22",hide_table_of_contents:!0},h="Josue",r={id:"bible/Josue/Josue 22",title:"Josue 22",description:"Chapter 22",source:"@site/docs/bible/Josue/Josue 22.md",sourceDirName:"bible/Josue",slug:"/bible/Josue/Josue_22",permalink:"/bibleNotes/docs/bible/Josue/Josue_22",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Josue/Josue 22.md",tags:[],version:"current",sidebarPosition:22,frontMatter:{sidebar_position:22,slug:"/bible/Josue/Josue_22",title:"Josue 22",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Josue 21",permalink:"/bibleNotes/docs/bible/Josue/Josue_21"},next:{title:"Josue 23",permalink:"/bibleNotes/docs/bible/Josue/Josue_23"}},i={},d=[{value:"Chapter 22",id:"chapter-22",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,a.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"josue",children:"Josue"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-22",children:"Chapter 22"}),"\n",(0,o.jsx)(t.p,{children:"The tribes of Ruben and Gad, and half the tribe of Manasses return to their possessions.  They build an altar by the side of the Jordan, which alarms the other tribes.  An embassage is sent to them, to which they give a satisfactory answer."}),"\n",(0,o.jsx)(n,{verse:1,children:"At the same time Josue called the Rubenites, and the Gadites, and the half tribe of Manasses,"}),"\n",(0,o.jsx)(n,{verse:2,children:"And said to them: You have done all that Moses the servant of the Lord commanded you: you have also obeyed me in all things,"}),"\n",(0,o.jsx)(n,{verse:3,children:"Neither have you left your brethren this long time, until this present day, keeping the commandment of the Lord your God."}),"\n",(0,o.jsx)(n,{verse:4,children:"Therefore as the Lord your God hath given your brethren rest and peace, as he promised: return, and go to your dwellings, and to the land of your possession, which Moses the servant of the Lord gave you beyond the Jordan:"}),"\n",(0,o.jsx)(n,{verse:5,children:"Yet so that you observe attentively, and in work fulfil the commandment and the law which Moses the servant of the Lord commanded you: that you love the Lord your God, and walk in all his ways, and keep all his commandments, and cleave to him, and serve him with all your heart, and with all your soul."}),"\n",(0,o.jsx)(n,{verse:6,children:"And Josue blessed them, and sent them away, and they returned to their dwellings."}),"\n",(0,o.jsx)(n,{verse:7,children:"Now to half the tribe of Manasses, Moses had given a possession in Basan: and therefore to the half that remained, Josue gave a lot among the rest of their brethren beyond the Jordan to the west. And when he sent them away to their dwellings and had blessed them,"}),"\n",(0,o.jsx)(n,{verse:8,children:"He said to them: With much substance and riches, you return to your settlements, with silver and gold, brass and iron, and variety of raiment: divide the prey of your enemies with your brethren."}),"\n",(0,o.jsx)(n,{verse:9,children:"So the children of Ruben, and the children of Gad, and the half tribe of Manasses returned, and parted from the children of Israel in Silo, which is in Chanaan, to go into Galaad the land of their possession, which they had obtained according to the commandment of the Lord by the hand of Moses."}),"\n",(0,o.jsx)(n,{verse:10,children:"And when they were come to banks of the Jordan, in the land of Chanaan, they built an altar immensely great near the Jordan."}),"\n",(0,o.jsx)(n,{verse:11,children:"And when the children of Israel had heard of it, and certain messengers brought them an account that the children of Ruben, and of Gad, and the half tribe of Manasses had built an altar in the land of Chanaan, upon the banks of the Jordan, over against the children of Israel:"}),"\n",(0,o.jsx)(n,{verse:12,children:"They all assembled in Silo, to go up and fight against them."}),"\n",(0,o.jsx)(n,{verse:13,children:"And in the mean time they sent to them into the land of Galaad, Phinees the son of Eleazar the priest,"}),"\n",(0,o.jsx)(n,{verse:14,children:"And ten princes with him, one of every tribe."}),"\n",(0,o.jsx)(n,{verse:15,children:"Who came to the children of Ruben, and of Gad, and the half tribe of Manasses, into the land of Galaad, and said to them:"}),"\n",(0,o.jsx)(n,{verse:16,children:"Thus saith all the people of the Lord: What meaneth this transgression? Why have you forsaken the Lord the God of Israel, building a sacrilegious altar, and revolting from the worship of him?"}),"\n",(0,o.jsx)(n,{verse:17,children:"Is it a small thing to you that you sinned with Beelphegor, and the stain of that crime remaineth in us to this day? and many of the people perished."}),"\n",(0,o.jsx)(n,{verse:18,children:"And you have forsaken the Lord to day, and to morrow his wrath will rage against all Israel."}),"\n",(0,o.jsx)(n,{verse:19,children:"But if you think the land of your possession to be unclean, pass over to the land wherein is the tabernacle of the Lord, and dwell among us: only depart not from the Lord, and from our society, by building an altar beside the altar of the Lord our God."}),"\n",(0,o.jsx)(n,{verse:20,children:"Did not Achan the son of Zare transgress the commandment of the Lord, and his wrath lay upon all the people of Israel? And he was but one man, and would to God he alone had perished in his wickedness."}),"\n",(0,o.jsx)(n,{verse:21,children:"And the children of Ruben, and of Gad, and of the half tribe of Manasses answered the princes of the embassage of Israel:"}),"\n",(0,o.jsx)(n,{verse:22,children:"The Lord the most mighty God, the Lord the most mighty God, he knoweth, and Israel also shall understand: If with the design of transgression we have set up this altar, let him not save us, but punish us immediately:"}),"\n",(0,o.jsx)(n,{verse:23,children:"And if we did it with that mind, that we might lay upon it holocausts, and sacrifice, and victims of peace offerings, let him require and judge:"}),"\n",(0,o.jsx)(n,{verse:24,children:"And not rather with this thought and design, that we should say: To morrow your children will say to our children: What have you to do with the Lord the God of Israel?"}),"\n",(0,o.jsx)(n,{verse:25,children:"The Lord hath put the river Jordan for a border between us and you, O ye children of Ruben, and ye children of Gad: and therefore you have no part in the Lord. And by this occasion your children shall turn away our children from the fear of the Lord. We therefore thought it best,"}),"\n",(0,o.jsx)(n,{verse:26,children:"And said: Let us build us an altar, not for holocausts, nor to offer victims,"}),"\n",(0,o.jsx)(n,{verse:27,children:"But for a testimony between us and you, and our posterity and yours, that we may serve the Lord, and that we may have a right to offer both holocausts, and victims and sacrifices of peace offerings: and that your children to morrow may not say to our children: You have no part in the Lord."}),"\n",(0,o.jsx)(n,{verse:28,children:"And if they will say so, they shall answer them: Behold the altar of the Lord, which our fathers made, not for holocausts, nor for sacrifice, but for a testimony between us and you."}),"\n",(0,o.jsx)(n,{verse:29,children:"God keep us from any such wickedness that we should revolt from the Lord, and leave off following his steps, by building an altar to offer holocausts, and sacrifices, and victims, beside the altar of the Lord our God, which is erected before his tabernacle."}),"\n",(0,o.jsx)(n,{verse:30,children:"And when Phinees the priest, and the princes of the embassage, who were with him, had heard this, they were satisfied: and they admitted most willingly the words of the children of Ruben, and Gad, and of the half tribe of Manasses,"}),"\n",(0,o.jsx)(n,{verse:31,children:"And Phinees the priest the son of Eleazar said to them: Now we know that the Lord is with us, because you are not guilty of this revolt, and you have delivered the children of Israel from the hand of the Lord."}),"\n",(0,o.jsx)(n,{verse:32,children:"And he returned with the princes from the children of Ruben and Gad, out of the land of Galaad, into the land of Chanaan, to the children of Israel, and brought them word again."}),"\n",(0,o.jsx)(n,{verse:33,children:"And the saying pleased all that heard it. And the children of Israel praised God, and they no longer said that they would go up against them, and fight, and destroy the land of their possession."}),"\n",(0,o.jsx)(n,{verse:34,children:"And the children of Ruben, and the children of Gad called the altar which they had built, Our testimony, that the Lord is God,"})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>h,x:()=>r});var o=n(14041);const a={},s=o.createContext(a);function h(e){const t=o.useContext(s);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:h(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);